func (svc *Intermediate) SetShards(value []foremanapi.ShardSpec) (err error) { // MARKER: Shards
	_data, err := json.Marshal(value)
	if err != nil {
		return errors.Trace(err)
	}
	return svc.SetConfig("Shards", string(_data))
}

// Workers is the maximum number of concurrent workers that process flow steps. Leave at -1 to let the engine derive the ceiling from each shard's connection budget and measured round-trip time. 0 stands up a replica that creates, awaits, and serves reads but never executes a task.
func (svc *Intermediate) Workers() (value int) { // MARKER: Workers
	_val := svc.Config("Workers")
	_i, _ := strconv.ParseInt(_val, 10, 64)
	return int(_i)
}

// SetWorkers sets the value of the configuration property.
func (svc *Intermediate) SetWorkers(value int) (err error) { // MARKER: Workers
	return svc.SetConfig("Workers", strconv.Itoa(value))
}

// TimeBudget is the default time budget for a single task step's execution, applied as the timeout on the task dispatch call. A flow may override it per-flow via FlowOptions.TimeBudget, up to a hard 15m ceiling; a task endpoint may declare a shorter budget of its own via sub.TimeBudget.
func (svc *Intermediate) TimeBudget() (value time.Duration) { // MARKER: TimeBudget
	_val := svc.Config("TimeBudget")
	_dur, _ := time.ParseDuration(_val)
	return _dur
}

// SetTimeBudget sets the value of the configuration property.
func (svc *Intermediate) SetTimeBudget(value time.Duration) (err error) { // MARKER: TimeBudget
	return svc.SetConfig("TimeBudget", value.String())
}

// DefaultPriority is the priority assigned to a flow when the caller does not specify one. Priority is an integer >= 1, lower numbers run first.
func (svc *Intermediate) DefaultPriority() (value int) { // MARKER: DefaultPriority
	_val := svc.Config("DefaultPriority")
	_i, _ := strconv.ParseInt(_val, 10, 64)
	return int(_i)
}

// SetDefaultPriority sets the value of the configuration property.
func (svc *Intermediate) SetDefaultPriority(value int) (err error) { // MARKER: DefaultPriority
	return svc.SetConfig("DefaultPriority", strconv.Itoa(value))
}

// MaxOpenConns pins every shard's connection pool to exactly this many open connections. Leave at 0 to let the engine size each pool from that shard's VirtualCPUs. Set it only when the connection budget is constrained by something the engine cannot see, such as a shared database or an external pooler.
func (svc *Intermediate) MaxOpenConns() (value int) { // MARKER: MaxOpenConns
	_val := svc.Config("MaxOpenConns")
	_i, _ := strconv.ParseInt(_val, 10, 64)
	return int(_i)
}

// SetMaxOpenConns sets the value of the configuration property.
func (svc *Intermediate) SetMaxOpenConns(value int) (err error) { // MARKER: MaxOpenConns
	return svc.SetConfig("MaxOpenConns", strconv.Itoa(value))
}
